/**
 * Note: Since the method calls exit() and uses static PhaseOptimizer.randomizeLoops(),
 * and the class is abstract, we use a Testable subclass and Mockito/PowerMock approach.
 * In a standard environment, we mock the dependencies.
 */
@RunWith(org.mockito.junit.MockitoJUnitRunner.class)
public class AbstractCommandLineRunner_run_TriageGen2Test {

    private TestableRunner runner;

    @Mock
    private CommandLineConfig mockConfig;

    @Mock
    private RunTimeStats mockRunTimeStats;

    // Since exit() is likely a method in the same class or a parent, 
    // we spy on the runner to verify the exit call.

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        runner = spy(new TestableRunner(mockConfig, mockRunTimeStats));
    }

    /**
     * Concrete implementation for testing the abstract class.
     */
    private static class TestableRunner extends AbstractCommandLineRunner {
        private final CommandLineConfig config;
        private final RunTimeStats runTimeStats;
        private int doRunReturnValue = 0;
        private Exception doRunException = null;

        public TestableRunner(CommandLineConfig config, RunTimeStats runTimeStats) {
            this.config = config;
            this.runTimeStats = runTimeStats;
        }

        @Override
        protected CommandLineConfig getCommandLineConfig() { return config; }
        @Override
        protected Object createCompiler() { return null; }
        @Override
        protected Object createOptions() { return null; }
        @Override
        protected com.google.javascript.jscomp.DiagnosticGroups getDiagnosticGroups() { return null; }
        @Override
        protected void initOptionsFromFlags(com.google.javascript.jscomp.CompilerOptions options) {}
        @Override
        protected void setRunOptions(com.google.javascript.jscomp.CompilerOptions options) throws java.io.IOException {}
        @Override
        protected Object getCompiler() { return null; }
        @Override
        protected java.io.PrintStream getErrorPrintStream() { return null; }
        @Override
        protected java.util.List<com.google.javascript.jscomp.JSSourceFile> createExterns() throws java.io.IOException { return null; }

        @Override
        protected int doRun() throws java.io.FlagUsageException, java.io.IOException {
            if (doRunException != null) {
                throw doRunException;
            }
            return doRunReturnValue;
        }

        @Override
        public void exit(RunTimeStats stats, Throwable error) {
            // Implementation for testing exit
        }

        // Accessors for testing
        public void setDoRunReturnValue(int val) { this.doRunReturnValue = val; }
        public void setDoRunException(Exception ex) { this.doRunException = ex; }
        public CommandLineConfig getConfig() { return config; }
        public RunTimeStats getRunTimeStats() { return runTimeStats; }
    }

    @Test
    public void testRun_SingleRunSuccess() throws Exception {
        runner.getConfig().computePhaseOrdering = false;
        runner.setDoRunReturnValue(1); // result != 0, loop should terminate

        runner.run();

        verify(runner.getRunTimeStats()).recordStartRun();
        verify(runner.getRunTimeStats()).recordEndRun();
        verify(runner).exit(eq(runner.getRunTimeStats()), isNull());
    }

    @Test
    public void testRun_MultipleRunsUntilSuccess() throws Exception {
        runner.getConfig().computePhaseOrdering = false;
        // Simulate: first run returns 0 (fail/continue), second run returns 1 (success/stop)
        doReturn(0).doReturn(1).when(runner).doRun();

        runner.run();

        verify(runner.getRunTimeStats(), times(2)).recordStartRun();
        verify(runner.getRunTimeStats(), times(2)).recordEndRun();
        verify(runner).exit(eq(runner.getRunTimeStats()), isNull());
    }

    @Test
    public void testRun_WithPhaseOrderingEnabled() throws Exception {
        // We use MockedStatic for PhaseOptimizer
        try (var mockedStatic = org.mockito.Mockito.mockStatic(PhaseOptimizer.class)) {
            runner.getConfig().computePhaseOrdering = true;
            runner.setDoRunReturnValue(1);

            runner.run();

            mockedStatic.verify(PhaseOptimizer::randomizeLoops, times(1));
            verify(runner).exit(eq(runner.getRunTimeStats()), isNull());
        }
    }

    @Test
    public void testRun_WithErrorInDoRun() throws Exception {
        runner.getConfig().computePhaseOrdering = false;
        RuntimeException exception = new RuntimeException("Test Exception");
        runner.setDoRunException(exception);

        runner.run();

        verify(runner.getRunTimeStats()).recordStartRun();
        // EndRun should NOT be called if exception is thrown before it
        verify(runner.getRunTimeStats(), never()).recordEndRun();
        verify(runner).exit(eq(runner.getRunTimeStats()), eq(exception));
    }

    @Test
    public void testRun_WithPhaseOrderingAndMultipleRuns() throws Exception {
        try (var mockedStatic = org.mockito.Mockito.mockStatic(PhaseOptimizer.class)) {
            runner.getConfig().computePhaseOrdering = true;
            // Set a high number of runs via reflection if NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER is constant
            // Assuming for test purposes we want to trigger the loop
            runner.setDoRunReturnValue(0); // Loop continues until runs limit is hit

            runner.run();

            mockedStatic.verify(PhaseOptimizer::randomizeLoops, times(1));
            // Since result remains 0, it should run NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER times
            // We check that exit is called with null error
            verify(runner).exit(eq(runner.getRunTimeStats()), isNull());
        }
    }
}
